/**
 * 拦截事件类型
 */
declare enum InterceptEvent {
    /** 创建工作项 */
    CreateWorkItem = 1001,
    /** 删除工作项 */
    DeleteWorkItem = 1002,
    /** 批量删除工作项 */
    BatchDeleteWorkItem = 1003,
    /** 恢复工作项 */
    RecoveryWorkItem = 1004,
    /** 终止工作项 */
    AbortWorkItem = 1005,
    /** 模板升级 */
    UpgradeTemplate = 1006,
    /** 批量模板升级 */
    BatchUpgradeTemplate = 1007,
    /** 导出工作项 */
    ExportWorkItem = 1008,
    /** 完成节点 */
    FinishNode = 2001,
    /** 删除节点 */
    DeleteNode = 2002,
    /** 恢复节点 */
    RecoveryNode = 2003,
    /** 回滚节点 */
    RollBackNode = 2004,
    /** 填写排期与估分 */
    EditSchedule = 2005,
    /** 变更状态 */
    UpdateState = 3001
}
/**
 * 拦截构成
 * 用于拦截用户行为，包括拦截位置、触发规则和提示等相关配置
 */
interface InterceptFeatureContext<T> {
    message: string;
    eventType: InterceptEvent;
    workItems: Array<BriefWorkItem & {
        /**
         * 当前触发事件，不同事件类型对应不同的 changedValue
         */
        changedValue?: {
            fieldInfo?: Array<{
                fieldKey: string;
                fieldType?: string;
                alias?: string;
                beforeFieldValue?: unknown;
                afterFieldValue?: unknown;
            }>;
            nodeInfo?: any;
            subTaskInfo?: any;
            transitionInfo?: any;
        };
    }>;
    customData: T;
}
